import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 연계 대상 고정값
const LINK_TARGET = 'NTS_EFILING';
// 가정: 연계 구분 값 (값 체계 미확정)
const LINK_TYPE = '신고';

@Controller('api/v1')
export class FnSfr02302Controller {
  @Post('/tax-filings/:taxFilingId/submit')
  @HttpCode(200)
  async submitTaxFiling(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    checks.inputOf(req.body);
    const id = req.params['taxFilingId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT tax_filing_id AS "taxFilingId", filing_type AS "filingType", ' +
          'attribution_month AS "attributionMonth", payment_month AS "paymentMonth", ' +
          'submission_year AS "submissionYear", total_amount AS "totalAmount", ' +
          'filing_status AS "filingStatus" ' +
          'FROM tax_filing WHERE tax_filing_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'TAX_FILING_NOT_FOUND', '신고서를 찾을 수 없습니다.');
      }
      const filing = rows[0] as Record<string, unknown>;
      // 가정: 작성 중(DRAFT) 신고서만 신고할 수 있다
      if (String(filing.filingStatus) !== 'DRAFT') {
        throw new ApiError(409, 'INVALID_STATE', '작성 중인 신고서만 신고할 수 있습니다.');
      }
      // 가정: 전자파일 규격 검증은 집계 금액과 연월 형식만 확인한다
      const month = /^\d{6}$/;
      const badMonth =
        (filing.attributionMonth != null && !month.test(String(filing.attributionMonth))) ||
        (filing.paymentMonth != null && !month.test(String(filing.paymentMonth)));
      if (filing.totalAmount == null || badMonth) {
        throw new ApiError(
          422,
          'ELECTRONIC_FILE_VALIDATION_FAILED',
          '전자파일 규격 검증에 실패했습니다. 집계 금액과 귀속·지급연월을 확인해 주세요.',
        );
      }
      // 가정: 전자파일 이름 규칙
      const period = String(filing.paymentMonth ?? filing.submissionYear ?? filing.attributionMonth ?? 'NA');
      const electronicFileName = String(filing.filingType) + '_' + period + '_' + id + '.txt';
      await db.query(
        'INSERT INTO link_log (requester_id, link_target, link_type, status, requested_at, request_summary, created_at, updated_at) ' +
          'VALUES (CAST(:userId AS bigint), :target, :linkType, \'REQUESTED\', now(), :summary, now(), now()) ' +
          'RETURNING link_log_id AS "linkLogId"',
        {
          userId: user.id,
          target: LINK_TARGET,
          linkType: LINK_TYPE,
          summary: electronicFileName,
        },
      );
      // TODO: 국세청 전송과 접수 결과(SUCCESS/FAILURE, 접수번호) 반영은 연계 규격이 없어 구현하지 못했다
      const out = await db.query(
        'SELECT tax_filing_id AS "taxFilingId", filing_status AS "filingStatus", ' +
          'filed_at AS "filedAt", result_message AS "resultMessage", receipt_number AS "receiptNumber" ' +
          'FROM tax_filing WHERE tax_filing_id = CAST(:id AS bigint)',
        { id },
      );
      return { ...(out[0] as Record<string, unknown>), electronicFileName };
    });
  }
}

