import { useState } from 'react';
import {
  call,
  Band,
  Badge,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Pairs,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02302Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [opened, setOpened] = useState(false);
  const [detail, setDetail] = useState<Row | undefined>(undefined);
  const [filingId, setFilingId] = useState<number | string>('');

  async function submit() {
    if (filingId === '') {
      throw new Error('신고할 신고서를 선택해 주세요.');
    }
    const res = await call('POST', '/tax-filings/' + filingId + '/submit', role, {});
    setResults([res, ...results.filter((r) => r.taxFilingId !== res.taxFilingId)]);
    setOpened(false);
    setFilingId('');
    notify('신고를 처리했습니다.');
  }

  if (detail) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setDetail(undefined)}>
          목록으로
        </button>
        <section className="box">
          <h2>신고 결과</h2>
          <Pairs
            items={[
              ['세무 신고서 ID', String(detail.taxFilingId)],
              ['신고 상태', <Badge value={detail.filingStatus} />],
              ['전자신고 일시', <DateText value={detail.filedAt} time />],
              ['전자신고 결과 메시지', String(detail.resultMessage ?? '')],
              ['접수번호', String(detail.receiptNumber ?? '')],
              ['생성된 국세청 전자파일 이름', String(detail.electronicFileName ?? '')],
            ]}
          />
        </section>
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>국세청 원천세 전자파일 신고</h2>
        <Band total={results.length}>
          <button onClick={() => setOpened(true)}>신고하기</button>
        </Band>
        <DataTable
          columns={[
            { key: 'taxFilingId', label: '세무 신고서 ID' },
            { key: 'filingStatus', label: '신고 상태', render: (r) => <Badge value={r.filingStatus} /> },
            { key: 'receiptNumber', label: '접수번호' },
            { key: 'electronicFileName', label: '전자파일 이름' },
            { key: 'filedAt', label: '전자신고 일시', render: (r) => <DateText value={r.filedAt} time /> },
          ]}
          rows={results}
          onRowClick={(r) => setDetail(r)}
          empty="아직 신고한 내역이 없습니다. 신고하기를 눌러 신고서를 선택해 주세요."
        />
      </section>
      {opened && (
        <Drawer title="전자파일 신고" onClose={() => setOpened(false)}>
          <Form
            onSubmit={submit}
            submit="신고"
            note="선택한 신고서로 국세청 규격 전자파일을 만들어 신고합니다."
          >
            <Field label="세무 신고서 ID" required wide>
              <LookupSelect
                table="tax_filing"
                role={role}
                value={filingId}
                onChange={setFilingId}
                placeholder="신고서 선택"
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
